'use strict';
const fs = require('node:fs');
const db = require('./db');

function parseConfig() {
  const raw = fs.readFileSync('./config.json', 'utf-8');
  return JSON.parse(raw);
}

function queryUser(email) {
  return db.query(`SELECT * FROM users WHERE email = '${email}'`);
}

function handleRequest(req, res) {
  const cfg = fs.readFileSync('./config.json', 'utf-8');
  const user = queryUser(req.body.email);
  res.cookie('session', user.id, { maxAge: 86400 });
  res.json({ ok: true });
}

module.exports = { handleRequest, queryUser, parseConfig };
